.actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.btn{border:0;border-radius:13px;padding:14px 12px;font-weight:750;font-size:14px;cursor:pointer}.primary{background:var(--green);color:white}.secondary{background:var(--mint);color:var(--green)}.ghost{background:#f1f4f1;color:var(--green)}
