/* HokeGo Storybook Quest: soft, warm, character-led adventure */
:root{--green:#527b69;--green2:#7aa58e;--mint:#e5f1e8;--gold:#e9b967;--ink:#34463f;--muted:#78877f;--paper:#f7f3e9;--white:#fffdf7;--red:#bd6b69}
body{background:radial-gradient(ellipse at 12% 0%,#fff3d9 0%,transparent 38%),radial-gradient(ellipse at 95% 22%,#e3f0e7 0%,transparent 34%),#f7f3e9;color:var(--ink)}
header{position:relative;overflow:hidden;background:linear-gradient(120deg,#dcebdd 0%,#f5e7c9 58%,#d8e9e4 100%);color:#38574a;border-radius:0 0 30px 30px;padding:25px 20px 30px;box-shadow:0 8px 24px #637c6520;border-bottom:1px solid #d6dfcf}
header:after{content:"✦  ✧  ✦";position:absolute;right:20px;top:18px;color:#c99b54;font-size:25px;letter-spacing:8px;opacity:.8}
.brand{color:#668d78;letter-spacing:.18em}.hero{font-size:30px;letter-spacing:.03em;color:#38574a;text-shadow:0 2px 0 #ffffffaa}.sub{color:#61786b}
.panel{background:#fffdf8;border:1px solid #e8e0cf;border-radius:21px;box-shadow:0 7px 22px #786e4e12}
h2{color:#526f5d}.muted{color:#78877f}
.unit{background:linear-gradient(110deg,#fffdf8,#f2f6ed);border:1px solid #e4e8d9;color:#34463f;border-radius:16px;box-shadow:0 3px 10px #66745b0d}
.unit:hover{border-color:#a9c4a8;background:#f4f8ef}
.num{background:linear-gradient(145deg,#d7e9d8,#f4e7c8);color:#557b65;box-shadow:0 2px 7px #879d7822}
.unit small{color:#78877f}.arrow{color:#85a48e}
.btn{border-radius:15px;box-shadow:0 4px 0 #c9c6b4,0 6px 14px #716b5012;transition:transform .12s,filter .12s}
.btn:active{transform:translateY(2px);box-shadow:0 2px 0 #c9c6b4}
.primary{background:linear-gradient(120deg,#739b80,#527b69);color:white;border:1px solid #8eb29a}
.secondary{background:linear-gradient(120deg,#f2dfb8,#ead09b);color:#6e5732;border:1px solid #e5c98e}
.ghost{background:#f0f1e9;color:#627668;border:1px solid #e0e3d5}
.stat{background:linear-gradient(145deg,#f3f7ee,#f8f0df);border:1px solid #e8e5d7}
.stat b{color:#648b72}.stat span{color:#78877f}
.topline{color:#78877f}.bar{background:#e9e8dc;height:9px}.bar>i{background:linear-gradient(90deg,#86b394,#e6bd72);box-shadow:0 0 8px #9abf9c66}
.level{display:inline-block;color:#94713e;background:#fbf0d8;padding:5px 10px;border-radius:99px;border:1px solid #eddbb6}
.question{color:#34463f;font-size:20px;text-shadow:none}
.choice{background:linear-gradient(110deg,#fffefa,#f5f7f0);border:1.5px solid #e2e6d9;color:#34463f;border-radius:15px;min-height:58px;box-shadow:0 3px 9px #6f765b0c}
.choice:hover:not(:disabled){border-color:#9fbea5;transform:translateY(-1px)}
.choice .letter{background:linear-gradient(145deg,#dcebdd,#c9dfd0);color:#557b65;border-radius:9px}
.choice.correct{border-color:#83b99b;background:#edf7ef;color:#345b43}
.choice.correct .letter{background:#a9d3b4}
.choice.wrong{border-color:#d69a91;background:#fff0eb;color:#854c46}
.choice.wrong .letter{background:#e9c1b8}
.feedback.good{background:#edf7ef;color:#345b43;border:1px solid #c8e2ce}
.feedback.bad{background:#fff0eb;color:#854c46;border:1px solid #edc9bf}
.resultbig b{color:#b28a45;text-shadow:none}
.tag{background:#f8efd9;color:#8b6b37;border:1px solid #ead9b5}
.reviewitem{border-color:#ebe5d8}
footer{color:#9a9b8c}
.character-hero{position:relative;display:flex;align-items:center;gap:10px;margin:12px 0 0;padding:8px 14px 0;min-height:125px}
.character-hero img{height:142px;width:auto;object-fit:contain;align-self:flex-end;filter:drop-shadow(0 5px 4px #59654b22)}
.character-hero .speech{background:#fffdf5;border:1px solid #e5d9bf;border-radius:17px;padding:11px 14px;color:#55715f;font-size:13px;line-height:1.55;box-shadow:0 4px 12px #8b80551a;position:relative}
.character-hero .speech:before{content:"";position:absolute;left:-7px;top:25px;width:12px;height:12px;background:#fffdf5;border-left:1px solid #e5d9bf;border-bottom:1px solid #e5d9bf;transform:rotate(45deg)}
.game-world{display:flex;align-items:center;gap:8px;color:#8b7957;font-size:11px;font-weight:700;margin-top:7px}
.game-world .star{color:#d5a858;font-size:15px}
@media(min-width:620px){.panel{padding:21px}.question{font-size:23px}.character-hero img{height:158px}}


