/* JK Maru Gothic: embedded locally for offline, consistent rendering */
@font-face{
  font-family:"JK Maru Gothic";
  src:url(data:font/otf;base64,) format("opentype");
  font-style:normal;
  font-weight:400 700;
  font-display:swap;
}
html,body,button,input,select,textarea,
.quest-header,.quest-header *,main,.quest-board,.quest-board *,
#quiz,#result,#review, .panel,.unit,.choice,.btn,.feedback,
h1,h2,h3,p,small,strong,span,label{
  font-family:"JK Maru Gothic","Yu Gothic",sans-serif !important;
}


/* Quiz page: always-visible route back to the platform home */
.quiz-home-nav{display:flex;justify-content:flex-end;margin:0 2px 8px}
.quiz-home-button{min-height:40px;padding:7px 17px;border:2px solid #795333;border-radius:12px;background:linear-gradient(180deg,#fff8e8,#f1dfb8);color:#68462d;font:700 14px "JK Maru Gothic","Yu Gothic",sans-serif;box-shadow:0 3px 0 #c6a77b;cursor:pointer}
.quiz-home-button:active{transform:translateY(2px);box-shadow:0 1px 0 #c6a77b}
/* Quest battle board: illustrated wooden frame, parchment and character guides */
body:has(#quiz:not(.hidden))>header{display:none}
body:has(#quiz:not(.hidden)) main{max-width:980px;padding:8px 12px 26px}
#quiz{width:100%}
